list_of_arguments_to_read = {
    "tool_name": str,                 # name of the tool the agent wants to call
    "verification_result": str,       # result from verify_financing_party (e.g., "Approved")
    "asset_compliance_result": str,   # result from check_asset_compliance (e.g., "Allowed")
    "design_structure": dict,         # result object from design_trust_structure (if any)
    "prospectus": dict,               # result object from generate_prospectus (if any)
    "episode_calls": list,            # ordered list of prior tool calls in this episode,
                                      # each entry is a dict with at least "tool_name" and "result"
}

# 2. Constants used by the policy
ALLOWED_VERIFICATION_RESULTS = {"Approved", "Accepted", "Positive"}
ALLOWED_ASSET_COMPLIANCE = {"Allowed", "Compliant"}
HIGH_RISK_TOOLS = {
    "design_trust_structure",
    "generate_prospectus",
    "submit_for_review",
}

# 3. Policy function
def policy(arguments: dict) -> tuple[bool, str]:
    """Allow or deny a tool call based on prerequisite compliance for high‑risk actions."""
    tool = arguments.get("tool_name")
    if not tool:
        return False, "Missing tool_name."

    # Low‑risk tools are always allowed
    if tool not in HIGH_RISK_TOOLS:
        return True, "Tool is low‑risk and always allowed."

    # Helper: retrieve the most recent result for a given tool from episode_calls
    calls = arguments.get("episode_calls", [])
    def last_result(name: str):
        for entry in reversed(calls):
            if entry.get("tool_name") == name:
                return entry.get("result")
        return None

    # ---- design_trust_structure -------------------------------------------------
    if tool == "design_trust_structure":
        ver_res = last_result("verify_financing_party")
        asset_res = last_result("check_asset_compliance")
        if ver_res is None or asset_res is None:
            return False, "Prerequisite verification or asset‑compliance result missing."
        if ver_res not in ALLOWED_VERIFICATION_RESULTS:
            return False, f"Financing‑party verification not approved (got '{ver_res}')."
        if asset_res not in ALLOWED_ASSET_COMPLIANCE:
            return False, f"Asset compliance not allowed (got '{asset_res}')."
        return True, "All prerequisites satisfied for design_trust_structure."

    # ---- generate_prospectus ----------------------------------------------------
    if tool == "generate_prospectus":
        design_res = last_result("design_trust_structure")
        asset_res = last_result("check_asset_compliance")
        if design_res is None:
            return False, "Trust structure has not been created yet."
        if not isinstance(design_res, dict) or not design_res.get("structure_id"):
            return False, "Invalid design_trust_structure result."
        if asset_res is None or asset_res not in ALLOWED_ASSET_COMPLIANCE:
            return False, "Asset compliance not allowed or missing."
        return True, "All prerequisites satisfied for generate_prospectus."

    # ---- submit_for_review -------------------------------------------------------
    if tool == "submit_for_review":
        design_res = last_result("design_trust_structure")
        prospectus_res = last_result("generate_prospectus")
        ver_res = last_result("verify_financing_party")
        asset_res = last_result("check_asset_compliance")

        if design_res is None:
            return False, "Missing design_trust_structure result."
        if prospectus_res is None:
            return False, "Missing generate_prospectus result."
        if not isinstance(design_res, dict) or not design_res.get("structure_id"):
            return False, "Invalid design_trust_structure result."
        if not isinstance(prospectus_res, dict) or not prospectus_res.get("prospectus_id"):
            return False, "Invalid generate_prospectus result."
        if ver_res is None or ver_res not in ALLOWED_VERIFICATION_RESULTS:
            return False, "Financing‑party verification not approved or missing."
        if asset_res is None or asset_res not in ALLOWED_ASSET_COMPLIANCE:
            return False, "Asset compliance not allowed or missing."
        return True, "All prerequisites satisfied for submit_for_review."

    # Fallback – unknown high‑risk tool
    return False, f"Tool '{tool}' is not recognized by the policy."

